const modal = document.getElementById('demo-modal');

document.getElementById('open-modal').addEventListener('nys-click', () => {
  modal.open = true;
});

document.getElementById('cancel-modal').addEventListener('nys-click', () => {
  modal.open = false;
});

document.getElementById('confirm-modal').addEventListener('nys-click', () => {
  modal.open = false;
});
